# 2. 处理请求 data 数据

## 2.1 需求分析

在之前的实现中，我们允许用户传入的`data`类型只能是纯对象，当传入的`data`是其他类型的时候，例如`URLSearchParams`对象，那么我们在发送请求的时候就会报错。所以我们需要对用户传入的`data`做一层处理。

根据需求，我们需要实现：当用户传入的`data`是`URLSearchParams`对象，那么我们会默认将请求头`Content-Type`设置为`application/x-www-form-urlencoded;charset=utf-8`。

## 2.2 代码实现

首先，我们在`src/helpers`目录下创建`data.ts`文件，用来处理`data`相关的辅助函数。

```typescript
// src/helpers/data.ts
import { isPlainObject } from "./util";

export function transformRequest(data: any): any {
  if (isPlainObject(data)) {
    return JSON.stringify(data);
  }
  return data;
}
```

然后，我们修改`src/xhr.ts`文件，在发送请求前对`config.data`进行转换。

```typescript
// src/xhr.ts

import { transformRequest } from "./helpers/data";

export default function xhr(config: AxiosRequestConfig): AxiosPromise {
  return new Promise((resolve) => {
    const {
      data = null,
      url,
      method = "get",
      headers,
      responseType,
      timeout,
    } = config;

    const request = new XMLHttpRequest();

    if (responseType) {
      request.responseType = responseType;
    }

    if (timeout) {
      request.timeout = timeout;
    }

    request.open(method.toUpperCase(), url, true);

    // 添加请求头
    Object.keys(headers).forEach((name) => {
      if (data === null && name.toLowerCase() === "content-type") {
        delete headers[name];
      } else {
        request.setRequestHeader(name, headers[name]);
      }
    });

    // 发送请求
    request.send(transformRequest(data));

    // 处理响应
    request.onreadystatechange = function handleLoad() {...};
    // 处理错误
    request.onerror = function handleError() {...};
    // 处理超时
    request.ontimeout = function handleTimeout() {...};
  });
}
```

OK，这样我们就实现了对请求`data`的处理，当`data`是普通对象的时候，我们会将其`JSON.stringify`。

但是，我们还需要处理`data`是`URLSearchParams`对象的情况，根据需求，当`data`是`URLSearchParams`对象的时候，我们需要将请求头`Content-Type`设置为`application/x-www-form-urlencoded;charset=utf-8`。

首先，我们需要判断`data`是不是`URLSearchParams`对象实例，我们在`src/helpers/util.ts`中添加一个工具函数`isURLSearchParams`。

```typescript
// src/helpers/util.ts

export function isURLSearchParams(val: any): val is URLSearchParams {
  return typeof val !== "undefined" && val instanceof URLSearchParams;
}
```

然后，我们修改`src/helpers/data.ts`文件。

```typescript
// src/helpers/data.ts
import { isPlainObject, isURLSearchParams } from "./util";

export function transformRequest(data: any): any {
  if (isPlainObject(data)) {
    return JSON.stringify(data);
  }
  if (isURLSearchParams(data)) {
    return data.toString();
  }
  return data;
}
```

接着，我们还需要修改`src/xhr.ts`文件，在设置请求头的时候，如果`data`是`URLSearchParams`类型，我们需要自动设置`Content-Type`。

```typescript
// src/xhr.ts
import { isPlainObject, isURLSearchParams } from "./helpers/util";
import { transformRequest } from "./helpers/data";

export default function xhr(config: AxiosRequestConfig): AxiosPromise {
  return new Promise((resolve) => {
    const {
      data = null,
      url,
      method = "get",
      headers,
      responseType,
      timeout,
    } = config;

    const request = new XMLHttpRequest();

    if (responseType) {
      request.responseType = responseType;
    }

    if (timeout) {
      request.timeout = timeout;
    }

    request.open(method.toUpperCase(), url, true);

    // 添加请求头
    Object.keys(headers).forEach((name) => {
      if (data === null && name.toLowerCase() === "content-type") {
        delete headers[name];
      } else {
        request.setRequestHeader(name, headers[name]);
      }
    });

    // 如果data是URLSearchParams对象，则设置Content-Type
    if (isURLSearchParams(data)) {
      request.setRequestHeader(
        "Content-Type",
        "application/x-www-form-urlencoded;charset=utf-8"
      );
    }

    // 发送请求
    request.send(transformRequest(data));

    // 处理响应
    request.onreadystatechange = function handleLoad() {...};
    // 处理错误
    request.onerror = function handleError() {...};
    // 处理超时
    request.ontimeout = function handleTimeout() {...};
  });
}
```

