# 4. 处理响应 data 数据

## 4.1 需求分析

在我们之前的实现中，当我们收到服务器返回的数据时，我们会原封不动的返回给用户，但是如果返回的数据是字符串类型，我们可能希望将其尝试转换成`JSON`对象，这样用户使用起来会更加方便。

所以，我们需要对响应`data`做一层处理，如果响应`data`是字符串类型，我们会尝试将其转换成`JSON`对象。

## 4.2 代码实现

首先，我们在`src/helpers`目录下的`data.ts`文件中添加一个`transformResponse`函数。

```typescript
// src/helpers/data.ts
import { isPlainObject, isURLSearchParams } from "./util";

export function transformRequest(data: any): any {
  if (isPlainObject(data)) {
    return JSON.stringify(data);
  }
  if (isURLSearchParams(data)) {
    return data.toString();
  }
  return data;
}

export function transformResponse(data: any): any {
  if (typeof data === "string") {
    try {
      data = JSON.parse(data);
    } catch (e) {
      // do nothing
    }
  }
  return data;
}
```

然后，我们修改`src/xhr.ts`文件，在收到响应后对`response.data`进行转换。

```typescript
// src/xhr.ts
import { transformRequest, transformResponse } from "./helpers/data";
import { processHeaders } from "./helpers/headers";

export default function xhr(config: AxiosRequestConfig): AxiosPromise {
  return new Promise((resolve) => {
    const {
      data = null,
      url,
      method = "get",
      headers,
      responseType,
      timeout,
    } = config;

    const request = new XMLHttpRequest();

    if (responseType) {
      request.responseType = responseType;
    }

    if (timeout) {
      request.timeout = timeout;
    }

    request.open(method.toUpperCase(), url, true);

    // 处理headers
    const processedHeaders = processHeaders(headers, data);

    // 添加请求头
    Object.keys(processedHeaders).forEach((name) => {
      if (data === null && name.toLowerCase() === "content-type") {
        delete processedHeaders[name];
      } else {
        request.setRequestHeader(name, processedHeaders[name]);
      }
    });

    // 如果data是URLSearchParams对象，则设置Content-Type
    if (isURLSearchParams(data)) {
      request.setRequestHeader(
        "Content-Type",
        "application/x-www-form-urlencoded;charset=utf-8"
      );
    }

    // 发送请求
    request.send(transformRequest(data));

    // 处理响应
    request.onreadystatechange = function handleLoad() {
      if (request.readyState !== 4) {
        return;
      }

      if (request.status === 0) {
        return;
      }

      const responseHeaders = request.getAllResponseHeaders();
      const responseData =
        responseType && responseType !== "text"
          ? request.response
          : request.responseText;
      const response: AxiosResponse = {
        data: transformResponse(responseData),
        status: request.status,
        statusText: request.statusText,
        headers: responseHeaders,
        config,
        request,
      };
      resolve(response);
    };
    // 处理错误
    request.onerror = function handleError() {...};
    // 处理超时
    request.ontimeout = function handleTimeout() {...};
  });
}
```

